std::vector<std::string> joint_map = { 
      "NOS_","NEC_","SHOR","ELBR","WRIR","SHOL","ELBL","WRIL",
      "HIPR","KNER","ANKR","HIPL","KNEL","ANKL",
      "EYER","EYEL","EARR","EARL"
    }; // default joint map 

// Plugin class. This shall be the only part that needs to be modified,
