int main(int argc, char const *argv[])
{
  Postural_metrics_assessmentPlugin plugin;
  json params;
  json all_inputs, input, output;

  // Set the parameters
  plugin.set_params(&params);

  // Set input data
  // read dummy json file
  ifstream input_file("dummy/simulated_hpe_inputs.json");
  if (input_file.is_open()) {
    input_file >> all_inputs;
    input_file.close();
  } else {
    cerr << "Unable to open input file" << endl;
    return 1;
  }

  int input_count = 0;
  for (const auto& input : all_inputs) {
    input_count++;
    cout << "Processing input #" << input_count << endl;

    // Set input data
    plugin.load_data(input);

    // Process data
    plugin.process(output);
    cout << "Output: " << output.dump(2) << endl;
  }

  return 0;
}

